import React from "react";
import { BrowserRouter, Routes, Route, Navigate } from "react-router-dom";
import { AuthProvider, useAuth } from "./context/AuthContext";

import LandingPage from "./pages/LandingPage";
import LoginPage from "./pages/LoginPage";
import SignupPage from "./pages/SignupPage";
import PatientDashboard from "./pages/PatientDashboard";
import DoctorDashboard from "./pages/DoctorDashboard";
import PredictPage from "./pages/PredictPage";
import ResultPage from "./pages/ResultPage";
import HistoryPage from "./pages/HistoryPage";
import DoctorsPage from "./pages/DoctorsPage";
import PatientsPage from "./pages/PatientsPage";
import "./assets/global.css";

// ── Route Guards ──────────────────────────────────────────────────────────────
const PrivateRoute = ({ children, role }) => {
  const { user, loading } = useAuth();
  if (loading) return <div className="loading-screen">Loading…</div>;
  if (!user) return <Navigate to="/" replace />;
  if (role && user.userType !== role) return <Navigate to="/dashboard" replace />;
  return children;
};

const PublicRoute = ({ children }) => {
  const { user, loading } = useAuth();
  if (loading) return <div className="loading-screen">Loading…</div>;
  if (user) return <Navigate to="/dashboard" replace />;
  return children;
};

const DashboardRedirect = () => {
  const { user } = useAuth();
  if (!user) return <Navigate to="/" replace />;
  return user.userType === "doctor"
    ? <Navigate to="/doctor/dashboard" replace />
    : <Navigate to="/patient/dashboard" replace />;
};

function AppRoutes() {
  return (
    <Routes>
      {/* Public */}
      <Route path="/" element={<PublicRoute><LandingPage /></PublicRoute>} />
      <Route path="/login/:userType" element={<PublicRoute><LoginPage /></PublicRoute>} />
      <Route path="/signup/:userType" element={<PublicRoute><SignupPage /></PublicRoute>} />

      {/* Role redirect */}
      <Route path="/dashboard" element={<PrivateRoute><DashboardRedirect /></PrivateRoute>} />

      {/* Patient routes */}
      <Route path="/patient/dashboard" element={<PrivateRoute role="patient"><PatientDashboard /></PrivateRoute>} />
      <Route path="/patient/predict" element={<PrivateRoute role="patient"><PredictPage /></PrivateRoute>} />
      <Route path="/patient/result" element={<PrivateRoute role="patient"><ResultPage /></PrivateRoute>} />
      <Route path="/patient/history" element={<PrivateRoute role="patient"><HistoryPage /></PrivateRoute>} />

      {/* Shared routes */}
      <Route path="/doctors" element={<PrivateRoute><DoctorsPage /></PrivateRoute>} />

      {/* Doctor routes */}
      <Route path="/doctor/dashboard" element={<PrivateRoute role="doctor"><DoctorDashboard /></PrivateRoute>} />
      <Route path="/doctor/patients" element={<PrivateRoute role="doctor"><PatientsPage /></PrivateRoute>} />

      {/* Fallback */}
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

export default function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppRoutes />
      </AuthProvider>
    </BrowserRouter>
  );
}
